/* ---------------- question sets ---------------- */
const SETS = [
 {id:"l1", lv:1, title:"Light or not?", zh:"看图：光源和材料", qs:[
  {pic:["fullmoon"], q:"The Moon looks bright at night. Is it a light source?", o:["No — it reflects light from the Sun.","Yes — it gives out its own light.","Yes — because it shines at night.","No — because it is too far away."], a:0,
   e:"The Moon does not give out its own light. It looks bright because it reflects light from the Sun.", z:"月亮不是光源，它反射太阳光。"},
  {pic:["firefly"], q:"This insect glows in the dark. Is it a light source?", o:["Yes — it gives out its own light.","No — it reflects moonlight.","No — living things cannot give out light.","No — it is too small."], a:0,
   e:"A firefly makes its own light, so it is a light source.", z:"萤火虫自己会发光，是光源。"},
  {pic:["sun"], q:"What is this, and does it give out its own light?", o:["the Sun — yes, it gives out its own light","the Moon — yes, it gives out its own light","the Sun — no, it only reflects light","the Moon — no, it only reflects light"], a:0,
   e:"This is the Sun, a star. It gives out its own light and is our most important light source.", z:"太阳是恒星，自己发光。"},
  {pic:["bikereflector"], q:"A bicycle reflector looks bright at night when a car comes near. Is it a light source?", o:["No — it reflects light from the car's headlights.","Yes — it gives out red light when a car is near.","Yes — it glows in the dark, so drivers can see it.","No — because it is made of plastic, not metal."], a:0,
   e:"A reflector gives out no light of its own. It looks bright only when light from the headlights falls on it and is reflected.", z:"反光片自己不发光，只反射车灯的光。"},
  {q:"Which of these is a light source?", o:["a lit candle","a mirror","the Moon","a diamond ring"], a:0,
   e:"The candle flame gives out light. A mirror, the Moon and a diamond only reflect light.", z:"点燃的蜡烛会发光，其他只是反射光。"},
  {pic:["litbulb"], q:"A light bulb is a light source ___.", o:["only when it is switched on","all the time, even when it is switched off","only in the daytime","never — it only reflects light"], a:0,
   e:"A bulb gives out light only when it is switched on.", z:"灯泡只有开着时才是光源。"},
  {pic:["frostedglass"], q:"Bathroom windows are often made of this glass. Some light passes through it, but we cannot see clearly through it. It is ___.", o:["translucent","transparent","opaque","a light source"], a:0,
   e:"Translucent materials let some light through, but we cannot see clearly through them.", z:"磨砂玻璃是半透明的。"},
  {q:"Clear glass lets most light pass through, and we can see clearly through it. Clear glass is ___.", o:["transparent","translucent","opaque","a light source"], a:0,
   e:"Transparent materials let most light through, so we can see clearly through them.", z:"透明玻璃是透明的。"},
  {q:"Which material is opaque?", o:["cardboard","clear plastic","tracing paper","frosted glass"], a:0,
   e:"Cardboard lets no light through. Clear plastic is transparent; tracing paper and frosted glass are translucent.", z:"纸板不透光，是不透明的。"},
  {pic:["sundial"], q:"This is a sundial. How does it tell the time?", o:["The shadow of its pointer moves as the Sun moves.","It gives out light at different times of the day.","Its pointer turns round slowly, like a clock hand.","It reflects moonlight onto the numbers at night."], a:0,
   e:"As the Sun moves across the sky, the shadow of the pointer moves. Where the shadow falls shows the time.", z:"日晷：太阳移动，指针的影子跟着移动。"}
 ]},
 {id:"l2", lv:2, title:"How we see", zh:"怎样看见东西、反射", qs:[
  {q:"How does Ali see a book on his desk at night when his lamp is on?", o:["Light from the lamp is reflected by the book into his eyes.","Light from his eyes travels to the book.","The book gives out its own light into his eyes.","Light from the lamp goes into his eyes; the book does not need light."], a:0,
   e:"The book is not a light source. Light from the lamp falls on the book and is reflected into Ali's eyes.", z:"灯 → 书 → 眼睛。"},
  {ch:"lt_seeingQ", q:"Which arrows show how the boy sees the book?", o:["P and R","Q and S","P and S","Q and R"], a:0, fix:true,
   e:"Light travels from the lamp to the book (P) and is reflected from the book into the eye (R). No light comes out of the eye.", z:"灯 → 书 → 眼睛：P 和 R。"},
  {q:"Sam is in a storeroom with no windows. When the door is shut and the light is off, he cannot see his white shirt. Why?", o:["There is no light to be reflected from the shirt into his eyes.","White things do not reflect light, so the shirt cannot be seen.","His eyes need time to give out enough light to see the shirt.","The shirt is opaque, so no light can pass through it to his eyes."], a:0,
   e:"We see an object only when light reflected from it enters our eyes. With no light at all, nothing can be seen.", z:"没有光，就没有光反射进眼睛。"},
  {q:"Can a cat see in a room with NO light at all?", o:["No — no light can enter its eyes.","Yes — a cat's eyes give out light.","Yes — cats do not need light to see.","Yes — but only things that are white."], a:0,
   e:"A cat needs much less light than we do, but in total darkness no light enters its eyes, so it cannot see.", z:"完全黑暗时猫也看不见。"},
  {ch:"lt_holes2", q:"Mei could not see the candle flame through the holes. What should she do?", o:["Move card Q so that all three holes are in a straight line.","Move the candle closer to card P so the flame is brighter.","Make the hole in card R bigger so more light can pass.","Light a second candle so that there is more light."], a:0,
   e:"Light travels in straight lines. The hole in card Q is not in line with the others, so card Q blocks the light.", z:"光沿直线传播，Q 的孔要和其他孔排成直线。"},
  {q:"Which observation shows that light travels in straight lines?", o:["A torch beam in a dusty room is straight.","A mirror reflects the light that falls on it.","Frosted glass lets some light through.","The Moon looks bright in the sky at night."], a:0,
   e:"The edges of a torch beam are straight lines. The other observations are about reflecting light or letting light through.", z:"手电筒的光束是直的。"},
  {q:"Which of these reflect light well?", st:["a mirror","smooth aluminium foil","black cloth","a polished steel spoon"], o:["A and B only","A, B and D only","A, C and D only","A, B, C and D"], a:1,
   e:"Smooth, shiny surfaces reflect light well. Black cloth is dull and dark, so it reflects very little light.", z:"光滑发亮的表面反光好，黑布反光很少。"},
  {q:"Why do cyclists wear vests with reflective strips at night?", o:["They reflect light from headlights, so drivers can see the cyclists.","They give out their own light, so drivers can see the cyclists.","They reflect light onto the road, so the cyclists can see the way.","They glow in the dark, so the cyclists do not need bicycle lamps."], a:0,
   e:"The strips are not light sources. They reflect light from the headlights back to the drivers' eyes.", z:"反光条反射车灯的光，司机就看得见。"},
  {q:"Which statement about a mirror is correct?", o:["It is opaque and reflects light well.","It is transparent because we can see things in it.","It is a light source because it is bright.","It is translucent because it lets some light through."], a:0,
   e:"No light passes through a mirror, so it is opaque. We see things in it because it reflects light very well.", z:"镜子是不透明的，但反光很好。"},
  {q:"Which of these is NOT a light source?", o:["the Moon","a star","lightning","a firefly"], a:0,
   e:"Stars, lightning and fireflies give out their own light. The Moon only reflects light from the Sun.", z:"月亮不是光源。"}
 ]},
 {id:"l3", lv:2, title:"Shadows", zh:"影子", qs:[
  {q:"A shadow is formed ___.", o:["on the side of the object away from the light","on the side of the object facing the light","only directly under the light source","only on the ground, never on a wall"], a:0,
   e:"The object blocks light, so the dark area is behind it, on the side away from the light.", z:"影子在物体背着光的那一边。"},
  {q:"Ken held a sheet of frosted glass between a torch and a screen. What did he see on the screen?", o:["a lighter shadow, because the glass lets some light through","no shadow at all, because light passes through all glass","a very dark shadow, because the glass blocks all light","a patch that is brighter than the rest of the screen"], a:0,
   e:"Frosted glass is translucent. It blocks some light, so it forms a shadow that is lighter than an opaque object's shadow.", z:"磨砂玻璃半透明 → 浅色影子。"},
  {q:"Which statements about shadows are correct?", st:["Opaque objects form dark shadows.","Transparent objects form very dark shadows.","Translucent objects form lighter shadows.","Shadows form because light travels in straight lines."], o:["A and C only","A, C and D only","B, C and D only","A, B, C and D"], a:1,
   e:"Transparent objects let most light through, so they form almost no shadow.", z:"透明物体几乎没有影子。"},
  {q:"Which object will form the DARKEST shadow?", o:["a wooden block","a sheet of tracing paper","a clear glass plate","a sheet of frosted glass"], a:0,
   e:"Wood is opaque and blocks all the light. Tracing paper and frosted glass are translucent; clear glass is transparent.", z:"木块不透明，影子最深。"},
  {q:"A red ball and a blue ball of the same size were placed, one at a time, at the same spot between a torch and a screen. How did their shadows compare?", o:["They had the same shape, size and darkness.","The red ball's shadow was red, and the blue ball's shadow was blue.","The red ball's shadow was bigger.","The blue ball's shadow was darker."], a:0,
   e:"Both balls are opaque and the same size at the same spot. A shadow is the dark area where light is blocked — it shows no colour.", z:"影子没有颜色，大小一样的不透明球影子一样。"},
  {q:"Which object can form BOTH a circular shadow and a rectangular shadow, depending on how it faces the torch?", o:["a can","a ball","a cube","an orange"], a:0,
   e:"A can with its round end facing the torch gives a circle; lying on its side it gives a rectangle. A ball and an orange always give circles; a cube never gives a circle.", z:"罐子：圆面对光是圆形，侧面对光是长方形。"},
  {q:"The shadow on a screen is a triangle. Which object could have made it?", o:["a cone, with its side facing the torch","a ball, with any side facing the torch","a can, with its round end facing the torch","an orange, held close to the torch"], a:0,
   e:"Seen from the side, a cone's outline is a triangle. The other objects give circles.", z:"圆锥侧面对着光 → 三角形影子。"},
  {q:"Lin wants the shadow of her hand on the wall to be BIGGER. What can she do?", o:["Move her hand closer to the torch.","Move her hand closer to the wall.","Move the torch further away from her hand.","Use a brighter torch."], a:0,
   e:"The closer the hand is to the light, the more light it blocks, so the shadow is bigger. Moving the hand towards the wall, or the torch away, makes it smaller. A brighter torch does not change the size.", z:"手离光越近，影子越大。"},
  {q:"At what time of the day is the shadow of a tree the SHORTEST?", o:["at noon","early in the morning","late in the afternoon","just before sunset"], a:0,
   e:"At noon the Sun is high in the sky, so shadows are shortest. When the Sun is low, shadows are long.", z:"中午太阳最高，影子最短。"},
  {q:"In the early morning, the Sun is in the east. Which way does the shadow of a lamp post point?", o:["towards the west","towards the east","towards the Sun","straight down, so there is no shadow"], a:0,
   e:"A shadow forms on the side away from the light. The Sun is in the east, so the shadow points west.", z:"太阳在东边，影子指向西边。"}
 ]},
 {id:"l4", lv:3, title:"Set-ups & data", zh:"实验装置和数据", qs:[
  {ch:"lt_posABC", q:"At which position will the toy's shadow on the screen be the BIGGEST?", o:["A","B","C"], a:0, fix:true,
   e:"A is closest to the torch. The closer the toy is to the light, the more light it blocks, so its shadow is bigger.", z:"离手电筒最近 → 影子最大。"},
  {ch:"lt_posABC", q:"The toy is moved from A to C. What happens to its shadow?", o:["It becomes smaller.","It becomes bigger.","It stays the same size.","It disappears."], a:0,
   e:"The toy moves further from the torch (and closer to the screen), so it blocks less light and its shadow becomes smaller.", z:"离手电筒越远，影子越小。"},
  {ch:"lt_screenPQR", q:"At which position of the screen is the toy's shadow the BIGGEST?", o:["P","Q","R"], a:2, fix:true,
   e:"The further the screen is from the toy, the more the light spreads out before it reaches the screen, so the shadow is bigger. R is the furthest.", z:"屏幕离物体越远，影子越大 → R。"},
  {ch:"lt_tdist", q:"What does the table show?", o:["The further the toy is from the torch, the smaller its shadow.","The further the toy is from the torch, the bigger its shadow.","The distance does not change the size of the shadow.","The shadow is always smaller than the toy."], a:0,
   e:"As the distance increased from 10 cm to 40 cm, the shadow height fell from 48 cm to 12 cm.", z:"距离越远，影子越小。"},
  {ch:"lt_tdist", q:"If the toy is placed 15 cm from the torch, the height of its shadow is most likely ___.", o:["about 32 cm","about 54 cm","about 20 cm","about 12 cm"], a:0,
   e:"15 cm is between 10 cm and 20 cm, so the shadow should be between 48 cm and 24 cm tall. Only 32 cm fits.", z:"15 cm 在 10 和 20 之间，影子应在 48 和 24 之间。"},
  {ch:"lt_tdist", q:"Which must be kept the SAME to make this a fair test?", st:["the toy used","the distance between the torch and the screen","the distance between the toy and the torch"], o:["A only","A and B only","B and C only","A, B and C"], a:1,
   e:"Only the distance between the toy and the torch was changed. The toy and the torch-to-screen distance must stay the same.", z:"只改变玩具和手电筒的距离，其他保持不变。"},
  {ch:"lt_tsheets", q:"Which sheet is opaque?", o:["K","L","M","N"], a:2, fix:true,
   e:"No light reached the sensor through sheet M (reading 0), so M lets no light through.", z:"读数 0 → 不透明。"},
  {ch:"lt_tsheets", q:"Which sheets are translucent?", o:["L and N only","K and L only","M and N only","K, L and N only"], a:0,
   e:"L and N let some light through (readings between 0 and 500). K let almost all the light through, so K is transparent.", z:"部分光通过 → 半透明：L 和 N。"},
  {ch:"lt_tsheets", q:"Each sheet was then held in front of a screen. Arrange their shadows from the LIGHTEST to the DARKEST.", o:["K, L, N, M","M, N, L, K","K, N, L, M","L, K, N, M"], a:0, fix:true,
   e:"The more light a sheet lets through, the lighter its shadow. K (490) lets the most light through and M (0) lets none.", z:"通过的光越多，影子越浅。"},
  {ch:"lt_sunpos", q:"At which position of the Sun is the stick's shadow the SHORTEST?", o:["P","Q","R"], a:1, fix:true,
   e:"At Q the Sun is high in the sky (around noon), so the shadow is shortest.", z:"太阳最高时影子最短。"}
 ]},
 {id:"l5", lv:3, title:"AL1 challenge", zh:"难题挑战", qs:[
  {ch:"lt_sunpos", q:"When the Sun is at P, what is the stick's shadow like?", o:["long, and pointing to the west","long, and pointing to the east","short, and pointing to the west","there is no shadow"], a:0,
   e:"At P the Sun is low in the east (early morning). The shadow is long and points away from the Sun — to the west.", z:"太阳在东方低处 → 影子长，指向西。"},
  {ch:"lt_tsun", q:"In which order were the readings taken during the day?", o:["P, Q, R, S","S, R, Q, P","R, Q, P, S","Q, P, S, R"], a:0, fix:true,
   e:"Morning shadows point west and get shorter as the Sun rises (P, then Q). The shortest shadow is at noon (R). Afternoon shadows point east (S).", z:"早上影子指向西、越来越短；中午最短；下午指向东。"},
  {ch:"lt_lamp", q:"What happens to the length of Ali's shadow on the ground as he walks from X to Y?", o:["It becomes longer.","It becomes shorter.","It stays the same length.","It disappears."], a:0,
   e:"Draw a straight line from the lamp past the top of Ali's head to the ground. The further he is from the lamp, the further from his feet that line reaches the ground, so his shadow gets longer. (This shadow is on the ground, not on a screen behind him.)", z:"从灯经过头顶画直线到地面：离灯越远，地上的影子越长。"},
  {q:"Jun wants a BIGGER shadow of a toy on a screen, but he must NOT move the toy. What can he do?", st:["Move the torch closer to the toy.","Move the screen further away from the toy.","Move the screen closer to the toy."], o:["A only","A and B only","B only","A, B and C"], a:1,
   e:"Moving the torch closer to the toy, or moving the screen further away from it, makes the shadow bigger. Moving the screen closer makes it smaller.", z:"灯靠近玩具或屏幕远离玩具，影子都变大。"},
  {q:"Which statements are correct?", st:["The Moon is a light source.","We see the Moon because it reflects light from the Sun into our eyes.","A mirror is opaque.","Light from our eyes helps us to see."], o:["A and B only","B and C only","B, C and D only","A, B and C only"], a:1,
   e:"The Moon only reflects sunlight, and our eyes do not give out light.", z:"月亮不是光源；眼睛不会发光。"},
  {ch:"lt_breflect", q:"Which surface is most likely a mirror?", o:["W","X","Y","Z"], a:1, fix:true,
   e:"A mirror is smooth and shiny, so it reflects the most light — the highest reading, X.", z:"镜子反光最多 → 读数最高。"},
  {q:"A sheet of tracing paper and a piece of cardboard of the same size and shape were placed, one at a time, at the same spot between a torch and a screen. How were their shadows different?", o:["They were the same size, but the tracing paper's shadow was lighter.","The tracing paper's shadow was smaller, because it is thinner.","The tracing paper formed no shadow, because light passes through it.","The cardboard's shadow was bigger, because cardboard is opaque."], a:0,
   e:"Shadow size depends on the outline and the distances, which were the same. Tracing paper lets some light through, so its shadow is lighter — not smaller.", z:"位置和大小一样 → 影子一样大；半透明的影子较浅。"},
  {ch:"lt_tfair", q:"Siti wants to find out if the distance between the torch and the toy affects the size of the shadow. Which two set-ups should she compare?", o:["P and Q","P and R","Q and S","R and S"], a:0,
   e:"P and Q differ only in the torch-to-toy distance. P and R use different toys; Q and S have different torch-to-screen distances; R and S differ in more than one thing.", z:"只能有一个条件不同：P 和 Q。"},
  {q:"Which statements about shadows outdoors are correct?", st:["A shadow points away from the Sun.","Shadows are longest at noon.","The direction of a shadow changes during the day.","Shadows in the late afternoon point towards the east."], o:["A and C only","A, C and D only","B and D only","A, B, C and D"], a:1,
   e:"Shadows are shortest at noon, not longest. In the late afternoon the Sun is in the west, so shadows point east.", z:"中午影子最短。下午太阳在西，影子指向东。"},
  {q:"In a room with the lights on, Ben sees his sister's face in a mirror. Which shows the path of the light?", o:["lamp → sister's face → mirror → Ben's eyes","Ben's eyes → mirror → sister's face","mirror → sister's face → Ben's eyes","lamp → mirror → sister's face → Ben's eyes"], a:0,
   e:"Light from the lamp falls on his sister's face and is reflected to the mirror. The mirror reflects it into Ben's eyes. Light never comes out of the eyes, and a mirror is not a light source.", z:"灯 → 妹妹的脸 → 镜子 → 眼睛。"}
 ]},
 {id:"l6", lv:4, title:"Full-mark answers", zh:"选出能拿满分的答案", qs:[
  {q:"A book was placed between a torch and a wall. Explain why a shadow formed on the wall. [2 marks]\nWhich answer gets full marks?", o:["The book is opaque and blocks light. Light travels in straight lines, so it cannot get behind the book.","The book is dark in colour and blocks light. Light travels in straight lines, so it cannot get behind the book.","The book is opaque and blocks light. The torch is switched on, so it gives out a lot of light onto the wall.","The book is dark in colour and blocks light. The torch is switched on, so it gives out a lot of light onto the wall."], a:0,
   n:["✓ Opaque + blocks light (1) + light travels in straight lines (1) — 2 marks.","½ Colour does not decide whether a shadow forms — the keyword is opaque. 1 mark for straight lines.","½ 1 mark for opaque + blocks light, but the torch giving out light does not explain the shadow. Missing: straight lines.","✗ No keywords: colour is not the reason, and the straight-line idea is missing."],
   e:"Use the keywords: the book is opaque and blocks light; light travels in straight lines, so it cannot reach the wall behind the book.", z:"关键词：书不透明（opaque）、挡住光、光沿直线传播。不要写“书是黑的”。"},
  {pic:["fullmoon"], q:"Explain why we can see the Moon at night. [1 mark]", o:["The Moon reflects light from the Sun, and this light enters our eyes.","The Moon reflects light from the Sun, so it looks bright in the night sky.","The Moon gives out its own light, and this light enters our eyes.","The Moon gives out its own light, so it looks bright in the night sky."], a:0,
   n:["✓ Says where the light comes from (the Sun) and where it goes (into our eyes).","½ \"Reflects light from the Sun\" is right, but say that the light enters our eyes.","✗ The Moon is not a light source.","✗ The Moon is not a light source, and the answer does not say the light enters our eyes."],
   e:"Name the light source (the Sun), say that the Moon reflects its light, and that this light enters our eyes.", z:"写清楚：太阳的光被月亮反射进我们的眼睛。"},
  {q:"Sam cannot see anything in a dark storeroom with no windows. Explain why. [1 mark]", o:["There is no light, so no light is reflected from the objects into his eyes.","It is too dark, so no light can come out of his eyes to see the objects.","The objects are opaque, so no light can pass through them into his eyes.","It is too dark in the room, so his eyes cannot see the objects at all."], a:0,
   n:["✓ Links \"no light\" to no light being reflected into his eyes.","✗ Our eyes do not give out light.","✗ We see objects by the light they reflect, not by light passing through them.","✗ Only repeats the question in other words — it does not explain."],
   e:"We see an object only when light reflected from it enters our eyes. With no light, nothing is reflected.", z:"看见东西需要光反射进眼睛；没有光，就没有光反射进眼睛。"},
  {ch:"lt_tsheets", q:"Lin chose sheet L for her bathroom window. Explain why it is suitable. [2 marks]", o:["L is translucent. It lets some light into the bathroom, but people outside cannot see in clearly.","L is transparent like clear glass. It lets some light into the bathroom, but people outside cannot see in clearly.","L is translucent. It lets some light into the bathroom, and its reading of 300 units is quite high.","L is transparent like clear glass. It lets some light into the bathroom, and its reading of 300 units is quite high."], a:0,
   n:["✓ The property (translucent) + both reasons (light comes in, people cannot see in) — 2 marks.","½ Wrong property: L is translucent (K is transparent). People CAN see clearly through clear glass.","½ The data is right, but say why it suits a bathroom: people outside cannot see in clearly.","✗ Wrong property, and no reason why it suits a bathroom."],
   e:"Use the data: L lets some light through (300 units), so it is translucent. Then say why that suits a bathroom: light comes in, but people cannot see in clearly.", z:"L 半透明：光能进来，外面的人看不清里面。要用关键词 translucent。"},
  {ch:"lt_posABC", q:"Ben moved the toy from C to A. State what happened to the shadow and explain why. [2 marks]", o:["The shadow became bigger, because the toy was closer to the torch and blocked more light.","The shadow became bigger, because the torch gave out more light when the toy was moved to A.","The shadow became much darker, because the toy was closer to the torch and blocked more light.","The shadow became much darker, because the torch gave out more light when the toy was moved to A."], a:0,
   n:["✓ The change (bigger) AND the reason (closer to the torch, blocks more light) — 2 marks.","½ The change is right, but the torch gives out the same light wherever the toy is — 1 mark.","½ The reason is right, but the toy is opaque in both places, so the darkness stays the same — its SIZE changes — 1 mark.","✗ Both wrong: the SIZE of the shadow changes, and the torch's light stays the same."],
   e:"Give the change and the reason: closer to the torch → blocks more light → bigger shadow.", z:"写变化（变大），也写原因（离手电筒更近，挡住更多光）。"},
  {q:"Explain why a mirror is NOT a light source. [1 mark]", o:["It does not give out its own light; it only reflects light that falls on it.","It is opaque, so no light from a torch can pass through it to the other side.","It is smooth and shiny, so it reflects the light from a torch very well.","It is not hot like a candle flame or the Sun, so it cannot give out any light."], a:0,
   n:["✓ The key idea: it does not give out its own light; it only reflects light.","✗ Being opaque has nothing to do with being a light source.","½ True, but also say that it does not give out its own light.","✗ Heat is not the test: a firefly is not hot, but it gives out its own light."],
   e:"A light source gives out its own light. A mirror does not — it only reflects light from a light source.", z:"光源自己发光；镜子不会，只会反射光。"},
  {ch:"lt_tsun", q:"Explain why the shadow at S points towards the east. [1 mark]", o:["In the afternoon the Sun is in the west, and a shadow forms on the side away from the Sun.","In the afternoon the Sun is in the east, so the shadow of the stick points east too.","The Sun appears to move across the sky during the day, so the shadow moves round with it.","In the afternoon the Sun is low in the sky, so the shadow of the stick is long."], a:0,
   n:["✓ Says where the Sun is (west) and that the shadow forms on the side away from it.","✗ A shadow points AWAY from the Sun, so the Sun must be in the west.","✗ True, but too vague: say where the Sun is, and that the shadow is on the other side.","✗ True, but it explains the LENGTH of the shadow, not its direction."],
   e:"A shadow always forms on the side away from the light. In the afternoon the Sun is in the west, so the shadow points east.", z:"下午太阳在西边，影子在背着太阳的一边 → 指向东。"},
  {pic:["frostedglass"], q:"A sheet of frosted glass was placed between a torch and a screen. Describe the shadow and explain why. [2 marks]", o:["A light shadow formed, because frosted glass is translucent and lets some light through.","A light shadow formed, because frosted glass is blurry and lets light pass through it.","A light shadow formed, because frosted glass is transparent and lets most light through.","No shadow formed, because frosted glass is a kind of glass, and light passes through glass."], a:0,
   n:["✓ The shadow (light) + the reason (translucent, lets SOME light through) — 2 marks.","½ \"Blurry\" is not the keyword (translucent), and say that it lets SOME light through — 1 mark.","½ Frosted glass is translucent, not transparent — 1 mark for the shadow.","✗ Frosted glass is not clear glass: it blocks some light, so a light shadow forms."],
   e:"Translucent → lets some light through and blocks some → a light (faint) shadow.", z:"半透明 → 挡住部分光 → 浅色影子。关键词：translucent、some light。"},
  {ch:"lt_tdist", q:"State the relationship between the distance of the toy from the torch and the height of its shadow. [1 mark]", o:["The further the toy is from the torch, the shorter its shadow.","The further the toy is from the torch, the taller its shadow.","When the distance of the toy changes, the height of its shadow changes.","The shadow was 48 cm tall when the toy was 10 cm from the torch."], a:0,
   n:["✓ Says HOW the height changes as the distance changes.","✗ The opposite of the results: 48 cm at 10 cm, but 12 cm at 40 cm.","½ True, but it does not say HOW the height changes.","✗ That is one result, not a relationship."],
   e:"A relationship answer says how one thing changes when the other changes: \"The further ___, the shorter ___.\"", z:"关系题：越……越……，只写一个结果不算。"},
  {pic:["bikereflector"], q:"Explain how a driver can see the reflector on a bicycle at night. [1 mark]", o:["Light from the car's headlights is reflected by the reflector into the driver's eyes.","The reflector gives out its own red light, which travels into the driver's eyes.","The reflector is smooth and shiny, so it reflects light very well at night.","Light from the driver's eyes travels to the reflector and is reflected back into his eyes."], a:0,
   n:["✓ The path of the light: headlights → reflector → driver's eyes.","✗ A reflector is not a light source.","½ True, but say whose light it reflects (the headlights') and where it goes (into the driver's eyes).","✗ Eyes do not give out light."],
   e:"Describe the path of the light: headlights → reflector → driver's eyes.", z:"车灯 → 反光片 → 司机的眼睛。"}
 ]}
];

/* ---------------- sort games (tap to classify) ---------------- */
const SORTS = [
 {id:"ls1", title:"Light source or not?", zh:"是不是光源", bins:[["S","Light source","光源"],["N","Not a light source","不是光源"]], items:[
  ["sun","S","The Sun gives out its own light — it is a star."],["firefly","S","A firefly makes its own light."],["candle","S","The flame gives out light."],
  ["litbulb","S","A lit bulb gives out light."],["torch","S","It gives out light when it is switched on."],["fire","S","Fire gives out light."],
  ["star","S","Stars give out their own light."],["lightning","S","Lightning gives out light."],["tvon","S","A screen that is on gives out light."],
  ["fullmoon","N","The Moon only reflects light from the Sun."],["mirror","N","A mirror only reflects light."],["bikereflector","N","It only reflects light from car headlights."],
  ["diamondring","N","A diamond sparkles because it reflects light."],["book","N","We see it because it reflects light."]]},
 {id:"ls2", title:"Transparent, translucent or opaque?", zh:"透明、半透明还是不透明", bins:[["T","Transparent","透明"],["L","Translucent","半透明"],["O","Opaque","不透明"]], items:[
  ["glasswindow","T","Clear glass lets most light through."],["specs","T","We can see clearly through the lenses."],["water","T","Clear water lets most light through."],
  ["glassjar","T","Clear glass lets most light through."],["frostedglass","L","Lets some light through, but we cannot see clearly through it."],["tracingpaper","L","Lets some light through."],
  ["tissuepaper","L","Thin tissue paper lets some light through."],["woodblock","O","No light passes through wood."],["metalcan","O","No light passes through metal."],
  ["cardbox","O","No light passes through cardboard."],["book","O","No light passes through a book."],["mirror","O","A mirror reflects light but lets none through."]]}
];

TOPIC({id:"light", lv:"P3/P4", icon:"🔦", title:"Light and shadows", zh:"光和影子",
  pics:PICS, emo:EMO, learn:LEARN, charts:CHARTS, sets:SETS, sorts:SORTS});
